package com.itemdroppingaccuracy;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Order in which inventory slots should be clicked. Slots are 0-27, laid out 4 columns x 7 rows
 * (slot = row * 4 + col).
 */
public enum ClickPattern
{
	ROW_BY_ROW("Row by row"),
	COLUMN_BY_COLUMN("Column by column"),
	SNAKE_ROWS("Snake rows"),
	SNAKE_COLUMNS("Snake columns"),
	/** Right two columns snaking down, then the left two columns snaking back up. */
	DU_SNAKE_ROWS("DU Snake Rows"),
	/** Left two columns snaking down, then the right two columns snaking back up. */
	DU_SNAKE_ROWS_LEFT("DU Snake Rows (left first)"),
	/** Right two columns snaking up from the bottom, then the left two columns snaking back down. */
	UD_SNAKE_ROWS("UD Snake Rows"),
	/** Left two columns snaking up from the bottom, then the right two columns snaking back down. */
	UD_SNAKE_ROWS_LEFT("UD Snake Rows (left first)"),
	CUSTOM("Custom");

	public static final int COLS = 4;
	public static final int ROWS = 7;
	public static final int SIZE = COLS * ROWS;

	private final String name;

	ClickPattern(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}

	/**
	 * @param custom 1-based slot list such as "1,2,3,4,8,7,6,5"; only used for CUSTOM. Slots not listed
	 *               are appended afterwards in row order.
	 * @return all 28 slots (0-based) in click order
	 */
	public List<Integer> order(String custom)
	{
		Set<Integer> out = new LinkedHashSet<>();
		switch (this)
		{
			case ROW_BY_ROW:
				for (int s = 0; s < SIZE; s++)
				{
					out.add(s);
				}
				break;
			case COLUMN_BY_COLUMN:
				for (int c = 0; c < COLS; c++)
				{
					for (int r = 0; r < ROWS; r++)
					{
						out.add(r * COLS + c);
					}
				}
				break;
			case SNAKE_ROWS:
				for (int r = 0; r < ROWS; r++)
				{
					for (int i = 0; i < COLS; i++)
					{
						int c = r % 2 == 0 ? i : COLS - 1 - i;
						out.add(r * COLS + c);
					}
				}
				break;
			case SNAKE_COLUMNS:
				for (int c = 0; c < COLS; c++)
				{
					for (int i = 0; i < ROWS; i++)
					{
						int r = c % 2 == 0 ? i : ROWS - 1 - i;
						out.add(r * COLS + c);
					}
				}
				break;
			case DU_SNAKE_ROWS:
				twoPassSnake(out, true, true);
				break;
			case DU_SNAKE_ROWS_LEFT:
				twoPassSnake(out, false, true);
				break;
			case UD_SNAKE_ROWS:
				twoPassSnake(out, true, false);
				break;
			case UD_SNAKE_ROWS_LEFT:
				twoPassSnake(out, false, false);
				break;
			case CUSTOM:
				if (custom != null)
				{
					for (String tok : custom.split("[,\\s]+"))
					{
						try
						{
							int n = Integer.parseInt(tok.trim());
							if (n >= 1 && n <= SIZE)
							{
								out.add(n - 1);
							}
						}
						catch (NumberFormatException ignored)
						{
							// skip junk
						}
					}
				}
				for (int s = 0; s < SIZE; s++)
				{
					out.add(s);
				}
				break;
		}
		return new ArrayList<>(out);
	}

	/**
	 * Two passes over the 7 rows, each covering a pair of columns and snaking left/right row by row. The first pass
	 * starts at the outer edge of its pair; the second pass covers the other pair going the opposite way and
	 * keeps the snake's direction so the path stays continuous (it turns around on the last row).
	 */
	private static void twoPassSnake(Set<Integer> out, boolean rightFirst, boolean downFirst)
	{
		int firstLeftCol = rightFirst ? 2 : 0;
		int secondLeftCol = rightFirst ? 0 : 2;
		boolean leftToRight = !rightFirst; // right-first starts at the right edge, heading left
		for (int pass = 0; pass < 2; pass++)
		{
			boolean down = pass == 0 ? downFirst : !downFirst;
			int leftCol = pass == 0 ? firstLeftCol : secondLeftCol;
			for (int k = 0; k < ROWS; k++)
			{
				int row = down ? k : ROWS - 1 - k;
				int a = row * COLS + leftCol;
				out.add(leftToRight ? a : a + 1);
				out.add(leftToRight ? a + 1 : a);
				leftToRight = !leftToRight;
			}
			leftToRight = !leftToRight; // the last row of a pass is followed by a turn-around, not a flip
		}
	}
}

package com.itemdroppingaccuracy;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup(ItemDroppingAccuracyConfig.GROUP)
public interface ItemDroppingAccuracyConfig extends Config
{
	String GROUP = "itemdroppingaccuracy";

	@ConfigSection(
		name = "Targets",
		description = "Which items and actions are part of a run",
		position = 0
	)
	String targetsSection = "targets";

	@ConfigSection(
		name = "Pattern",
		description = "The order you should click in",
		position = 1
	)
	String patternSection = "pattern";

	@ConfigSection(
		name = "Display",
		description = "Overlays and colours",
		position = 2
	)
	String displaySection = "display";

	@ConfigSection(
		name = "Advanced",
		description = "Timing and hotkeys",
		position = 4,
		closedByDefault = true
	)
	String advancedSection = "advanced";

	@Range(min = 0, max = 28)
	@ConfigItem(
		keyName = "itemsPerRun",
		name = "Items per run",
		description = "How many items make up one run (26 = a full inventory minus two tools or stacks). A run only starts when at least this many target items are in the inventory, so a few leftovers are not tracked as a tiny run. 0 = every target item, however few.",
		section = targetsSection,
		position = 0
	)
	default int itemsPerRun()
	{
		return 26;
	}

	@ConfigItem(
		keyName = "includeItems",
		name = "Only these items",
		description = "Comma separated item names (* wildcard allowed) or ids. Leave blank to target everything that is not excluded.<br>Example: Empty bucket pack",
		section = targetsSection,
		position = 1
	)
	default String includeItems()
	{
		return "";
	}

	@ConfigItem(
		keyName = "excludeItems",
		name = "Excluded items",
		description = "Comma separated item names (* wildcard allowed) or ids that are never part of a run.<br>Example: Barbarian rod, Feather, Coins",
		section = targetsSection,
		position = 2
	)
	default String excludeItems()
	{
		return "Barbarian rod, Feather, Coins";
	}

	@ConfigItem(
		keyName = "excludeNoted",
		name = "Exclude noted items",
		description = "Never treat noted items (e.g. noted buckets) as targets.",
		section = targetsSection,
		position = 3
	)
	default boolean excludeNoted()
	{
		return true;
	}

	@ConfigItem(
		keyName = "actions",
		name = "Click actions",
		description = "Comma separated menu options that count as a click on a target (the left-click option of the item).",
		section = targetsSection,
		position = 4
	)
	default String actions()
	{
		return "Drop, Open";
	}

	@ConfigItem(
		keyName = "pattern",
		name = "Pattern",
		description = "The order the overlay guides you through.",
		section = patternSection,
		position = 0
	)
	default ClickPattern pattern()
	{
		return ClickPattern.DU_SNAKE_ROWS;
	}

	@ConfigItem(
		keyName = "customPattern",
		name = "Custom pattern",
		description = "Used when Pattern is Custom. Inventory slots 1-28 (left to right, top to bottom) in click order, e.g. 1,5,9,13,2,6,10,14.<br>Slots you leave out follow in row order.",
		section = patternSection,
		position = 1
	)
	default String customPattern()
	{
		return "";
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "showAhead",
		name = "Items to show ahead",
		description = "How many upcoming items are highlighted at once.",
		section = patternSection,
		position = 2
	)
	default int showAhead()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "showNumbers",
		name = "Show step numbers",
		description = "Number the highlighted items in click order.",
		section = patternSection,
		position = 3
	)
	default boolean showNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPatternOverlay",
		name = "Show pattern overlay",
		description = "Highlight the items to click next in the inventory.",
		section = displaySection,
		position = 0
	)
	default boolean showPatternOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showStatsOverlay",
		name = "Show stats overlay",
		description = "Show accuracy, time and perfect-run counters.",
		section = displaySection,
		position = 1
	)
	default boolean showStatsOverlay()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "nextColor",
		name = "Next item colour",
		description = "Colour of the item to click now.",
		section = displaySection,
		position = 2
	)
	default Color nextColor()
	{
		return new Color(0, 255, 90);
	}

	@Alpha
	@ConfigItem(
		keyName = "upcomingColor",
		name = "Upcoming item colour",
		description = "Colour of the items after the next one.",
		section = displaySection,
		position = 3
	)
	default Color upcomingColor()
	{
		return new Color(255, 200, 0);
	}

	@Alpha
	@ConfigItem(
		keyName = "missedColor",
		name = "Missed item colour",
		description = "Colour of items that were skipped or whose click failed. They are clicked after the rest of the pattern.",
		section = displaySection,
		position = 4
	)
	default Color missedColor()
	{
		return new Color(255, 50, 50);
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "confirmTicks",
		name = "Confirm window (ticks)",
		description = "How many game ticks to wait for a clicked item to leave its slot before the click counts as a miss.",
		section = advancedSection,
		position = 0
	)
	default int confirmTicks()
	{
		return 3;
	}

	@Range(min = 3, max = 120)
	@ConfigItem(
		keyName = "idleSeconds",
		name = "Idle timeout (seconds)",
		description = "An unfinished run is abandoned after this long without a click.",
		section = advancedSection,
		position = 1
	)
	default int idleSeconds()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "resetKey",
		name = "Reset hotkey",
		description = "Resets the current run and session stats.",
		section = advancedSection,
		position = 2
	)
	default Keybind resetKey()
	{
		return Keybind.NOT_SET;
	}
}

package com.itemdroppingaccuracy;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.Point;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedQueue;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.game.ItemManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.util.Text;

@PluginDescriptor(
	name = "Item Dropping Accuracy",
	description = "Tracks click accuracy and speed when dropping or opening inventory items, with a click-pattern overlay",
	tags = {"click", "accuracy", "drop", "open", "pack", "trainer", "stats", "streak"}
)
/**
 * Tracks click accuracy and speed while dropping/opening inventory items.
 *
 * <p>Everything is event driven: nothing runs per frame here, and an idle game tick only checks two
 * empty collections. All state is written on the client thread; the fields read by the overlays are
 * volatile (or replaced as immutable snapshots) so the render thread never needs a lock.
 * The plugin makes no network calls and writes config only when a run finishes.
 */
public class ItemDroppingAccuracyPlugin extends Plugin
{
	private static final long RAW_MATCH_WINDOW_NS = 500_000_000L;
	private static final long RAW_MISS_DELAY_NS = 400_000_000L;
	private static final int MAX_RAW_CLICKS = 50;
	private static final int LATE_CONFIRM_TICKS = 10;
	private static final String PERFECT_KEY = "perfectRuns";
	private static final String STREAK_KEY = "perfectStreak";
	private static final String BEST_STREAK_KEY = "bestPerfectStreak";
	private static final String BEST_TIME_PREFIX = "bestTime";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemDroppingAccuracyConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private PatternOverlay patternOverlay;

	@Inject
	private StatsOverlay statsOverlay;

	// ---- client-thread state ----
	private final int[] invIds = new int[ClickPattern.SIZE];
	private final int[] invQty = new int[ClickPattern.SIZE];
	private final int[] prevIds = new int[ClickPattern.SIZE];
	private final int[] prevQty = new int[ClickPattern.SIZE];
	private final Map<Integer, Attempt> pending = new HashMap<>();
	/** Clicks that timed out but whose item may still leave a little late; matched before calling a loss "automatic". */
	private final List<Attempt> expired = new ArrayList<>();
	/** Clicks on target items that were not tracked (run already full); their items leaving is expected. */
	private final Map<Integer, Integer> ignoredClicks = new HashMap<>();
	private final Map<Integer, Boolean> targetCache = new HashMap<>();
	private final Queue<RawClick> rawClicks = new ConcurrentLinkedQueue<>();
	private Set<String> actionSet = Collections.emptySet();
	// Config values are cached here (see parseConfig) because config getters are not free and some are read per frame.
	private List<Integer> patternOrder = ClickPattern.ROW_BY_ROW.order("");
	private int itemsPerRun;
	private int confirmTicks;
	private long idleNs;
	private final Map<Integer, Long> bestTimes = new HashMap<>();
	private ItemFilter includeFilter = new ItemFilter("");
	private ItemFilter excludeFilter = new ItemFilter("");
	private long lastClickNs;
	/** Pattern position of the latest click; the overlay continues from here so one slip does not derail the rest. */
	private int cursor = -1;
	/** Slots that were skipped or failed; they stay red and are queued after the rest of the pattern. */
	private final Set<Integer> missedSlots = new HashSet<>();
	private long lastHitClickNs;

	// ---- state read by overlays (render thread) ----
	@Getter
	private volatile List<Integer> upcomingOrder = Collections.emptyList();
	@Getter
	private volatile Map<Integer, Integer> upcomingRanks = Collections.emptyMap();
	@Getter
	private volatile Set<Integer> missedView = Collections.emptySet();

	@Getter
	private volatile boolean showPatternOverlay;
	@Getter
	private volatile boolean showStatsOverlay;
	@Getter
	private volatile boolean showNumbers;
	@Getter
	private volatile int showAhead;
	@Getter
	private volatile Color nextColor = Color.GREEN;
	@Getter
	private volatile Color upcomingColor = Color.YELLOW;
	@Getter
	private volatile Color missedColor = Color.RED;

	@Getter
	private volatile boolean active;
	@Getter
	private volatile boolean finished;
	@Getter
	private volatile boolean patternBroken;
	/** A target item left the inventory without one of our clicks (e.g. it opened on its own): the run failed. */
	@Getter
	private volatile boolean autoFailed;
	@Getter
	private volatile int targetTotal;
	@Getter
	private volatile int hits;
	@Getter
	private volatile int misses;
	@Getter
	private volatile long startNs;
	@Getter
	private volatile long finalElapsedMs;
	@Getter
	private volatile int readyTarget;
	@Getter
	private volatile long bestTimeMs;
	@Getter
	private volatile int sessionRuns;
	@Getter
	private volatile int sessionHits;
	@Getter
	private volatile int sessionMisses;
	@Getter
	private volatile long sessionBestRunMs;
	@Getter
	private volatile int sessionPerfectRuns;
	@Getter
	private volatile int totalPerfectRuns;
	/** Consecutive perfect runs; any imperfect finished run resets it. Saved between sessions. */
	@Getter
	private volatile int perfectStreak;
	@Getter
	private volatile int bestPerfectStreak;

	private final MouseAdapter mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (SwingUtilities.isLeftMouseButton(e))
			{
				rawClicks.add(new RawClick(System.nanoTime(), e.getPoint()));
				while (rawClicks.size() > MAX_RAW_CLICKS)
				{
					rawClicks.poll();
				}
			}
			return e;
		}
	};

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.resetKey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(ItemDroppingAccuracyPlugin.this::resetAll);
		}
	};

	@Provides
	ItemDroppingAccuracyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ItemDroppingAccuracyConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(patternOverlay);
		overlayManager.add(statsOverlay);
		mouseManager.registerMouseListener(mouseListener);
		keyManager.registerKeyListener(hotkeyListener);
		totalPerfectRuns = loadInt(PERFECT_KEY);
		perfectStreak = loadInt(STREAK_KEY);
		bestPerfectStreak = loadInt(BEST_STREAK_KEY);
		clientThread.invoke(() ->
		{
			parseConfig();
			refreshInventory();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(patternOverlay);
		overlayManager.remove(statsOverlay);
		mouseManager.unregisterMouseListener(mouseListener);
		keyManager.unregisterKeyListener(hotkeyListener);
		pending.clear();
		rawClicks.clear();
		targetCache.clear();
		bestTimes.clear();
		upcomingOrder = Collections.emptyList();
		upcomingRanks = Collections.emptyMap();
		resetCounters();
		sessionRuns = 0;
		sessionHits = 0;
		sessionMisses = 0;
		sessionBestRunMs = 0;
		sessionPerfectRuns = 0;
	}

	// ------------------------------------------------------------------ events

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!ItemDroppingAccuracyConfig.GROUP.equals(e.getGroup()) || isStateKey(e.getKey()))
		{
			return; // not ours, or just the stats this plugin saved itself
		}
		clientThread.invoke(() ->
		{
			parseConfig();
			recompute();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() != GameState.LOGGED_IN)
		{
			abandonRun();
		}
	}

	@Subscribe
	public void onOverlayMenuClicked(OverlayMenuClicked e)
	{
		if (e.getEntry().getMenuAction() == MenuAction.RUNELITE_OVERLAY
			&& e.getOverlay() == statsOverlay
			&& StatsOverlay.RESET_OPTION.equals(e.getEntry().getOption()))
		{
			resetAll();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged e)
	{
		if (e.getContainerId() != InventoryID.INV)
		{
			return;
		}
		System.arraycopy(invIds, 0, prevIds, 0, ClickPattern.SIZE);
		System.arraycopy(invQty, 0, prevQty, 0, ClickPattern.SIZE);
		readInventory(e.getItemContainer());

		// An attempt is confirmed once its slot changed AND the inventory really lost one of that item.
		// Checking the slot alone would count an accidental drag/swap of two items as a successful drop.
		Map<Integer, Integer> lost = new HashMap<>();
		Iterator<Map.Entry<Integer, Attempt>> it = pending.entrySet().iterator();
		while (it.hasNext())
		{
			Attempt a = it.next().getValue();
			if (invIds[a.slot] == a.itemId && invQty[a.slot] >= a.quantity)
			{
				continue; // still there
			}
			int left = lost.computeIfAbsent(a.itemId, id -> Math.max(0, total(id, prevIds, prevQty) - total(id, invIds, invQty)));
			if (left > 0)
			{
				lost.put(a.itemId, left - 1);
				it.remove();
				registerHit(a);
			}
		}
		if (active)
		{
			checkUnclickedLosses(lost);
		}
		recompute();
		checkCompletion();
	}

	/**
	 * Any target item that left the inventory without a click of ours (for example an item that opens itself
	 * when left idle) fails the run. Late confirmations of clicks that already timed out are not counted.
	 */
	private void checkUnclickedLosses(Map<Integer, Integer> lost)
	{
		Set<Integer> seen = new HashSet<>();
		for (int id : prevIds)
		{
			if (id <= 0 || !seen.add(id) || !isTarget(id))
			{
				continue;
			}
			int unexplained = lost.containsKey(id) ? lost.get(id) : Math.max(0, total(id, prevIds, prevQty) - total(id, invIds, invQty));
			Iterator<Attempt> late = expired.iterator();
			while (unexplained > 0 && late.hasNext())
			{
				Attempt a = late.next();
				if (a.itemId == id && (invIds[a.slot] != id || invQty[a.slot] < a.quantity))
				{
					late.remove();
					registerHit(a);
					unexplained--;
				}
			}
			int ignored = ignoredClicks.getOrDefault(id, 0);
			if (unexplained > 0 && ignored > 0)
			{
				int used = Math.min(unexplained, ignored);
				ignoredClicks.put(id, ignored - used);
				unexplained -= used;
			}
			if (unexplained > 0 && !autoFailed)
			{
				autoFailed = true;
				registerMiss(); // one penalty, like a wrong-order run
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (e.getParam1() != InterfaceID.Inventory.ITEMS)
		{
			return;
		}
		String option = e.getMenuOption() == null ? "" : Text.removeTags(e.getMenuOption()).toLowerCase();
		int slot = e.getParam0();
		int itemId = e.getItemId();
		if (!actionSet.contains(option) || itemId <= 0 || slot < 0 || slot >= ClickPattern.SIZE || !isTarget(itemId))
		{
			// Not a click on a target; if a run is active the raw click is reported as a miss on the next tick.
			return;
		}

		if (!active && countAllTargets() < itemsPerRun)
		{
			return; // fewer items than a full run (leftovers): not tracked
		}

		consumeRawClick();
		long now = System.nanoTime();

		if (!active)
		{
			startRun(now);
		}
		else if (hits + pending.size() >= targetTotal)
		{
			ignoredClicks.merge(itemId, 1, Integer::sum);
			return;
		}
		lastClickNs = now;

		if (pending.containsKey(slot))
		{
			registerMiss();
			return;
		}

		List<Integer> order = upcomingOrder;
		boolean offPattern = !order.isEmpty() && order.get(0) != slot;
		if (offPattern && !patternBroken)
		{
			// Wrong order: one penalty for the whole run, which then counts as failed accuracy-wise.
			patternBroken = true;
			registerMiss();
		}
		if (!missedSlots.contains(slot) && patternIndex(slot) > cursor)
		{
			// Anything the player jumped over is flagged red and gets queued after the rest of the pattern.
			for (int due : order)
			{
				if (due == slot)
				{
					break;
				}
				if (!missedSlots.contains(due))
				{
					missedSlots.add(due);
				}
			}
			cursor = patternIndex(slot);
		}
		pending.put(slot, new Attempt(slot, itemId, invQty[slot], client.getTickCount(), now, offPattern));
		recompute();
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		long now = System.nanoTime();
		int tick = client.getTickCount();

		boolean changed = false;
		Iterator<Map.Entry<Integer, Attempt>> it = pending.entrySet().iterator();
		while (it.hasNext())
		{
			Attempt a = it.next().getValue();
			if (tick - a.tick >= confirmTicks)
			{
				it.remove();
				a.expiredAt = tick;
				expired.add(a);
				missedSlots.add(a.slot); // the click never registered: red, and retried after the pattern
				registerMiss();
				changed = true;
			}
		}

		if (!expired.isEmpty())
		{
			expired.removeIf(a -> tick - a.expiredAt > LATE_CONFIRM_TICKS);
		}

		RawClick rc;
		while ((rc = rawClicks.peek()) != null && now - rc.ns > RAW_MISS_DELAY_NS)
		{
			rawClicks.poll();
			if (active && inInventory(rc.point))
			{
				registerMiss();
			}
		}

		if (active && now - lastClickNs > idleNs)
		{
			abandonRun();
			return;
		}

		// Nothing else changes between ticks, so an idle tick does no more than the checks above.
		if (changed)
		{
			recompute();
			checkCompletion();
		}
	}

	// ------------------------------------------------------------------ run logic

	private void startRun(long now)
	{
		resetCounters();
		active = true;
		finished = false;
		startNs = now;
		lastClickNs = now;
		lastHitClickNs = now;
		targetTotal = countTargets();
		bestTimeMs = loadBest(targetTotal);
	}

	private static int total(int itemId, int[] ids, int[] qty)
	{
		int sum = 0;
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] == itemId)
			{
				sum += qty[i];
			}
		}
		return sum;
	}

	private void registerHit(Attempt a)
	{
		hits++;
		sessionHits++;
		missedSlots.remove(a.slot);
		lastHitClickNs = Math.max(lastHitClickNs, a.clickNs);
	}

	private void registerMiss()
	{
		if (!active)
		{
			return;
		}
		misses++;
		sessionMisses++;
	}

	private void checkCompletion()
	{
		if (!active)
		{
			return;
		}
		boolean allHit = hits >= targetTotal;
		boolean outOfTargets = pending.isEmpty() && upcomingOrder.isEmpty();
		if (allHit || outOfTargets)
		{
			if (hits > 0)
			{
				finishRun();
			}
			else
			{
				abandonRun();
			}
		}
	}

	private int patternIndex(int slot)
	{
		return patternOrder.indexOf(slot);
	}

	private void finishRun()
	{
		finalElapsedMs = Math.max(0, (lastHitClickNs - startNs) / 1_000_000L);
		active = false;
		finished = true;
		sessionRuns++;
		if (misses == 0 && !patternBroken && !autoFailed && hits >= targetTotal)
		{
			sessionPerfectRuns++;
			totalPerfectRuns++;
			configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, PERFECT_KEY, totalPerfectRuns);
			perfectStreak++;
			if (perfectStreak > bestPerfectStreak)
			{
				bestPerfectStreak = perfectStreak;
				configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, BEST_STREAK_KEY, bestPerfectStreak);
			}
			configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, STREAK_KEY, perfectStreak);
		}
		else if (perfectStreak != 0)
		{
			perfectStreak = 0;
			configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, STREAK_KEY, 0);
		}
		cursor = -1;
		missedSlots.clear();
		if (misses == 0 && (sessionBestRunMs == 0 || finalElapsedMs < sessionBestRunMs))
		{
			sessionBestRunMs = finalElapsedMs;
		}
		if (hits == targetTotal && (bestTimeMs == 0 || finalElapsedMs < bestTimeMs))
		{
			bestTimeMs = finalElapsedMs;
			saveBest(targetTotal, finalElapsedMs);
		}
		pending.clear();
		recompute();
	}

	private void abandonRun()
	{
		active = false;
		finished = false;
		pending.clear();
		resetCounters();
		recompute();
	}

	private void resetCounters()
	{
		active = false;
		finished = false;
		patternBroken = false;
		autoFailed = false;
		expired.clear();
		ignoredClicks.clear();
		cursor = -1;
		missedSlots.clear();
		targetTotal = 0;
		hits = 0;
		misses = 0;
		startNs = 0;
		finalElapsedMs = 0;
	}

	private void resetAll()
	{
		pending.clear();
		rawClicks.clear();
		resetCounters();
		sessionRuns = 0;
		sessionHits = 0;
		sessionMisses = 0;
		sessionBestRunMs = 0;
		sessionPerfectRuns = 0;
		perfectStreak = 0;
		configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, STREAK_KEY, 0);
		recompute();
	}

	// ------------------------------------------------------------------ inventory / targets

	private void refreshInventory()
	{
		readInventory(client.getItemContainer(InventoryID.INV));
		recompute();
	}

	private void readInventory(ItemContainer container)
	{
		Arrays.fill(invIds, -1);
		Arrays.fill(invQty, 0);
		if (container == null)
		{
			return;
		}
		Item[] items = container.getItems();
		for (int i = 0; i < items.length && i < ClickPattern.SIZE; i++)
		{
			if (items[i].getId() > 0)
			{
				invIds[i] = items[i].getId();
				invQty[i] = items[i].getQuantity();
			}
		}
	}

	private void parseConfig()
	{
		includeFilter = new ItemFilter(config.includeItems());
		excludeFilter = new ItemFilter(config.excludeItems());
		Set<String> set = new HashSet<>();
		for (String s : config.actions().split(","))
		{
			String t = s.trim().toLowerCase();
			if (!t.isEmpty())
			{
				set.add(t);
			}
		}
		actionSet = set;
		targetCache.clear();

		patternOrder = config.pattern().order(config.customPattern());
		itemsPerRun = config.itemsPerRun();
		confirmTicks = config.confirmTicks();
		idleNs = config.idleSeconds() * 1_000_000_000L;
		showPatternOverlay = config.showPatternOverlay();
		showStatsOverlay = config.showStatsOverlay();
		showNumbers = config.showNumbers();
		showAhead = config.showAhead();
		nextColor = config.nextColor();
		upcomingColor = config.upcomingColor();
		missedColor = config.missedColor();
	}

	private boolean isTarget(int itemId)
	{
		Boolean cached = targetCache.get(itemId);
		if (cached != null)
		{
			return cached;
		}
		ItemComposition comp = itemManager.getItemComposition(itemId);
		String name = comp.getName();
		boolean result = true;
		if (config.excludeNoted() && comp.getNote() != -1)
		{
			result = false;
		}
		else if (excludeFilter.matches(itemId, name))
		{
			result = false;
		}
		else if (!includeFilter.isEmpty() && !includeFilter.matches(itemId, name))
		{
			result = false;
		}
		targetCache.put(itemId, result);
		return result;
	}

	private int countAllTargets()
	{
		int count = 0;
		for (int s = 0; s < ClickPattern.SIZE; s++)
		{
			if (invIds[s] > 0 && isTarget(invIds[s]))
			{
				count++;
			}
		}
		return count;
	}

	private int countTargets()
	{
		int count = countAllTargets();
		return itemsPerRun > 0 ? Math.min(itemsPerRun, count) : count;
	}

	/** Rebuilds the list of slots still to click, in pattern order. */
	private void recompute()
	{
		List<Integer> order = patternOrder;

		missedSlots.removeIf(slot -> !pending.containsKey(slot) && (invIds[slot] <= 0 || !isTarget(invIds[slot])));

		// Main pass: not-yet-reached slots in pattern order. Retry pass: missed slots (and anything behind the cursor).
		int start = active ? cursor + 1 : 0;
		List<Integer> main = new ArrayList<>();
		List<Integer> retry = new ArrayList<>();
		for (int idx = 0; idx < order.size(); idx++)
		{
			int slot = order.get(idx);
			if (invIds[slot] <= 0 || pending.containsKey(slot) || !isTarget(invIds[slot]))
			{
				continue;
			}
			if (idx >= start && !missedSlots.contains(slot))
			{
				main.add(slot);
			}
			else
			{
				retry.add(slot);
			}
		}
		List<Integer> up = new ArrayList<>(main);
		up.addAll(retry);

		int limit;
		if (active && itemsPerRun == 0)
		{
			// "Every item" run: anything still in the inventory belongs to this run, so it only ends when all are done.
			targetTotal = Math.max(targetTotal, hits + pending.size() + up.size());
			limit = up.size();
		}
		else if (active)
		{
			limit = Math.max(0, targetTotal - hits - pending.size());
		}
		else
		{
			limit = itemsPerRun > 0 ? itemsPerRun : ClickPattern.SIZE;
		}
		if (up.size() > limit)
		{
			up = new ArrayList<>(up.subList(0, limit));
		}
		missedView = Collections.unmodifiableSet(new HashSet<>(missedSlots));

		Map<Integer, Integer> ranks = new HashMap<>();
		for (int i = 0; i < up.size(); i++)
		{
			ranks.put(up.get(i), i);
		}
		upcomingOrder = Collections.unmodifiableList(up);
		upcomingRanks = Collections.unmodifiableMap(ranks);

		if (!active)
		{
			readyTarget = countTargets();
			if (!finished)
			{
				bestTimeMs = loadBest(readyTarget);
			}
		}
	}

	// ------------------------------------------------------------------ raw clicks

	private void consumeRawClick()
	{
		long now = System.nanoTime();
		RawClick match = null;
		for (RawClick rc : rawClicks)
		{
			if (now - rc.ns <= RAW_MATCH_WINDOW_NS)
			{
				match = rc;
			}
		}
		if (match != null)
		{
			rawClicks.remove(match);
		}
	}

	private boolean inInventory(Point p)
	{
		Widget inv = client.getWidget(InterfaceID.Inventory.ITEMS);
		return inv != null && !inv.isHidden() && inv.getBounds().contains(p);
	}

	// ------------------------------------------------------------------ best time persistence

	private int loadInt(String key)
	{
		String v = configManager.getConfiguration(ItemDroppingAccuracyConfig.GROUP, key);
		try
		{
			return v == null ? 0 : Integer.parseInt(v);
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}

	private long loadBest(int count)
	{
		if (count <= 0)
		{
			return 0;
		}
		// Read from the config store once per item count, then serve from memory.
		return bestTimes.computeIfAbsent(count, c ->
		{
			String v = configManager.getConfiguration(ItemDroppingAccuracyConfig.GROUP, BEST_TIME_PREFIX + c);
			try
			{
				return v == null ? 0L : Long.parseLong(v);
			}
			catch (NumberFormatException ex)
			{
				return 0L;
			}
		});
	}

	private void saveBest(int count, long ms)
	{
		bestTimes.put(count, ms);
		configManager.setConfiguration(ItemDroppingAccuracyConfig.GROUP, BEST_TIME_PREFIX + count, ms);
	}

	private static boolean isStateKey(String key)
	{
		return PERFECT_KEY.equals(key) || STREAK_KEY.equals(key) || BEST_STREAK_KEY.equals(key)
			|| (key != null && key.startsWith(BEST_TIME_PREFIX));
	}

	// ------------------------------------------------------------------ helpers

	/** Elapsed run time for display. */
	public long elapsedMs()
	{
		if (finished)
		{
			return finalElapsedMs;
		}
		if (!active)
		{
			return 0;
		}
		return (System.nanoTime() - startNs) / 1_000_000L;
	}

	private static final class Attempt
	{
		final int slot;
		final int itemId;
		final int quantity;
		final int tick;
		final long clickNs;
		final boolean offPattern;
		int expiredAt;

		Attempt(int slot, int itemId, int quantity, int tick, long clickNs, boolean offPattern)
		{
			this.slot = slot;
			this.itemId = itemId;
			this.quantity = quantity;
			this.tick = tick;
			this.clickNs = clickNs;
			this.offPattern = offPattern;
		}
	}

	private static final class RawClick
	{
		final long ns;
		final Point point;

		RawClick(long ns, Point point)
		{
			this.ns = ns;
			this.point = point;
		}
	}
}

package com.itemdroppingaccuracy;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

/** Matches items against a comma separated list of names (case-insensitive, * wildcard) or item ids. */
public class ItemFilter
{
	private final List<Integer> ids = new ArrayList<>();
	private final List<Pattern> names = new ArrayList<>();

	public ItemFilter(String csv)
	{
		if (csv == null)
		{
			return;
		}
		for (String raw : csv.split(","))
		{
			String tok = raw.trim().toLowerCase();
			if (tok.isEmpty())
			{
				continue;
			}
			if (tok.matches("\\d+"))
			{
				try
				{
					ids.add(Integer.parseInt(tok));
				}
				catch (NumberFormatException ignored)
				{
					// too large, ignore
				}
				continue;
			}
			names.add(Pattern.compile(glob(tok)));
		}
	}

	private static String glob(String tok)
	{
		StringBuilder sb = new StringBuilder();
		StringBuilder lit = new StringBuilder();
		for (char c : tok.toCharArray())
		{
			if (c == '*')
			{
				if (lit.length() > 0)
				{
					sb.append(Pattern.quote(lit.toString()));
					lit.setLength(0);
				}
				sb.append(".*");
			}
			else
			{
				lit.append(c);
			}
		}
		if (lit.length() > 0)
		{
			sb.append(Pattern.quote(lit.toString()));
		}
		return sb.toString();
	}

	public boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty();
	}

	public boolean matches(int itemId, String name)
	{
		if (ids.contains(itemId))
		{
			return true;
		}
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase();
		for (Pattern p : names)
		{
			if (p.matcher(n).matches())
			{
				return true;
			}
		}
		return false;
	}
}

package com.itemdroppingaccuracy;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Highlights the next inventory items to click, numbered. */
public class PatternOverlay extends WidgetItemOverlay
{
	private static final BasicStroke STROKE_NEXT = new BasicStroke(2.5f);
	private static final BasicStroke STROKE_UPCOMING = new BasicStroke(1.5f);

	private final ItemDroppingAccuracyPlugin plugin;

	@Inject
	private PatternOverlay(ItemDroppingAccuracyPlugin plugin)
	{
		this.plugin = plugin;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem item)
	{
		if (!plugin.isShowPatternOverlay())
		{
			return;
		}
		if (item.getWidget() == null)
		{
			return;
		}
		int slot = item.getWidget().getIndex();
		Integer rank = plugin.getUpcomingRanks().get(slot);
		boolean missed = plugin.getMissedView().contains(slot);
		// Missed items always stay visible; everything else only shows within the look-ahead.
		if (rank == null || (rank >= plugin.getShowAhead() && !missed))
		{
			return;
		}

		Rectangle b = item.getCanvasBounds();
		boolean next = rank == 0;
		Color base = missed ? plugin.getMissedColor() : next ? plugin.getNextColor() : plugin.getUpcomingColor();

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int fillAlpha = next ? 70 + (int) (40 * (1 + Math.sin(System.currentTimeMillis() / 150.0)) / 2) : 35;
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), Math.min(fillAlpha, base.getAlpha())));
		g.fill(b);
		g.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), base.getAlpha()));
		g.setStroke(next ? STROKE_NEXT : STROKE_UPCOMING);
		g.draw(b);

		if (plugin.isShowNumbers() && rank < plugin.getShowAhead())
		{
			g.setFont(FontManager.getRunescapeSmallFont());
			String text = String.valueOf(rank + 1);
			g.setColor(Color.BLACK);
			g.drawString(text, b.x + 3, b.y + 12);
			g.setColor(Color.WHITE);
			g.drawString(text, b.x + 2, b.y + 11);
		}
	}
}

package com.itemdroppingaccuracy;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class StatsOverlay extends OverlayPanel
{
	static final String RESET_OPTION = "Reset";
	private static final int PANEL_WIDTH = 190;

	private final ItemDroppingAccuracyPlugin plugin;

	@Inject
	private StatsOverlay(ItemDroppingAccuracyPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, RESET_OPTION, "Item Dropping Accuracy"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isShowStatsOverlay())
		{
			return null;
		}

		boolean active = plugin.isActive();
		boolean finished = plugin.isFinished();
		int hits = plugin.getHits();
		int misses = plugin.getMisses();
		int total = plugin.getTargetTotal();

		String status;
		Color statusColor;
		boolean auto = plugin.isAutoFailed();
		boolean broken = plugin.isPatternBroken() || auto;
		if (active)
		{
			status = auto ? "Auto-opened" : broken ? "Wrong order" : "Running";
			statusColor = broken ? Color.ORANGE : Color.GREEN;
		}
		else if (finished)
		{
			status = auto ? "Failed (auto)" : broken ? "Failed (order)" : misses == 0 ? "Perfect!" : "Complete";
			statusColor = broken ? Color.ORANGE : misses == 0 ? Color.CYAN : Color.YELLOW;
		}
		else
		{
			status = "Ready";
			statusColor = Color.LIGHT_GRAY;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text("Item Dropping Accuracy").build());
		line("Status", status, statusColor);
		if (!active && !finished)
		{
			line("Items", String.valueOf(plugin.getReadyTarget()), Color.WHITE);
		}

		if (active || finished)
		{
			line("Progress", hits + " / " + total, Color.WHITE);
			line("Accuracy", accuracy(hits, misses), accuracyColor(hits, misses));
			line("Time", seconds(plugin.elapsedMs()), Color.WHITE);
		}

		if (plugin.getBestTimeMs() > 0)
		{
			int count = active || finished ? total : plugin.getReadyTarget();
			line("Best (" + count + ")", seconds(plugin.getBestTimeMs()), Color.LIGHT_GRAY);
		}

		if (plugin.getTotalPerfectRuns() > 0 || plugin.getSessionPerfectRuns() > 0)
		{
			line("Perfect", plugin.getSessionPerfectRuns() + " (" + plugin.getTotalPerfectRuns() + " total)", Color.CYAN);
			line("Streak", plugin.getPerfectStreak() + " (best " + plugin.getBestPerfectStreak() + ")", Color.CYAN);
		}

		if (plugin.getSessionRuns() > 0)
		{
			line("Session", plugin.getSessionRuns() + " runs, " + percent(plugin.getSessionHits(), plugin.getSessionMisses()), Color.LIGHT_GRAY);
			if (plugin.getSessionBestRunMs() > 0)
			{
				line("Best clean", seconds(plugin.getSessionBestRunMs()), Color.LIGHT_GRAY);
			}
		}

		return super.render(graphics);
	}

	private void line(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}

	static String seconds(long ms)
	{
		return (ms / 1000) + "." + (ms / 100 % 10) + "s";
	}

	/** hits/clicks as a percentage with one decimal, rounded, without going through String.format. */
	private static String tenths(int hits, int clicks)
	{
		int t = (int) ((hits * 1000L + clicks / 2) / clicks);
		return (t / 10) + "." + (t % 10);
	}

	static String percent(int hits, int misses)
	{
		int clicks = hits + misses;
		return clicks == 0 ? "-" : tenths(hits, clicks) + "%";
	}

	static String accuracy(int hits, int misses)
	{
		int clicks = hits + misses;
		if (clicks == 0)
		{
			return "-";
		}
		return tenths(hits, clicks) + "% (" + hits + "/" + clicks + ")";
	}

	private static Color accuracyColor(int hits, int misses)
	{
		int clicks = hits + misses;
		if (clicks == 0)
		{
			return Color.WHITE;
		}
		double pct = 100.0 * hits / clicks;
		return pct >= 95 ? Color.GREEN : pct >= 85 ? Color.YELLOW : Color.ORANGE;
	}
}

